<div class="toolbar"><div><p class="eyebrow">Your selection</p><h1>장바구니</h1></div><a href="<?= $this->e($url) ?>/catalog">계속 쇼핑하기</a></div>
<?php if ($quote === null): ?><section class="panel empty"><h2><?= $cart === [] ? '장바구니가 비어 있습니다' : '장바구니 상품을 확인해 주세요' ?></h2><p>판매가 중지되거나 재고가 변경된 상품이 있다면 장바구니를 비운 뒤 다시 담아 주세요.</p><a class="button" href="<?= $this->e($url) ?>/catalog">상품 둘러보기</a></section>
<?php else: ?><div class="cols"><section class="panel table-wrap"><table><thead><tr><th>상품</th><th class="num">가격</th><th>수량</th></tr></thead><tbody><?php foreach ($quote['items'] as $item): ?><tr><td><strong><?= $this->e($item['name']) ?></strong><br><small><?= $this->e($item['options']) ?></small></td><td class="num"><?= number_format($item['price']) ?>원</td><td><form method="post" action="<?= $this->e($url) ?>/cart" class="row"><?php $this->insert('_csrf') ?><input type="hidden" name="variant_id" value="<?= $this->e($item['variant_id']) ?>"><input aria-label="<?= $this->e($item['name']) ?> 수량" type="number" name="quantity" value="<?= $item['quantity'] ?>" min="1" max="99"><button name="action" value="update" class="secondary">변경</button><button name="action" value="remove" class="secondary">삭제</button></form></td></tr><?php endforeach ?></tbody></table></section>
<aside class="panel"><h2>주문 금액</h2><div class="summary-line"><span>상품 합계</span><strong><?= number_format($quote['subtotal']) ?>원</strong></div><div class="summary-line"><span>배송비</span><strong><?= number_format($quote['shipping']) ?>원</strong></div><div class="summary-line total"><span>총 합계</span><span><?= number_format($quote['total']) ?>원</span></div><a class="button" href="<?= $this->e($url) ?>/checkout">주문하기</a><?php if ($user === null): ?><p class="muted">로그인 후 주문할 수 있습니다.</p><?php endif ?></aside></div><?php endif ?>
<?php if ($cart !== []): ?><form method="post" action="<?= $this->e($url) ?>/cart"><?php $this->insert('_csrf') ?><button name="action" value="clear" class="secondary">장바구니 비우기</button></form><?php endif ?>
